xml.Script:
        clBlue   := '0033EE';
        clGreen  := '00AA00';
        clRed    := 'DD0000';
        clOrange := 'FF7700';
        clYellow := 'FFEE00';

        R := 0.5;

        sAngle := Pi * 2 / 3;
        N := 60;
        for i := 0 to N - 1 do begin
            x[i] := R * cos(2 * Pi / N * i);
            y[i] := R * sin(2 * Pi / N * i);
        end;

        az := sqrt(2) / 4;
        bz := sqrt(3) / 2;
        H := 2 * R * az * 1.5;
        D := H/3;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

Macro.Script:
i1 := i mod N;
i2 := (i + 1) mod N;
Inc(i);
